local library = loadstring(
    game:HttpGet(
        'https://raw.githubusercontent.com/DozeIsOkLol/UILibarySource/refs/heads/main/Zinzo%20UI%20Lib'
    )
)()
local window = library:window('The Glass Bridge')
local folder = window:folder('Admin (Affects Others)')
local folder2 = window:folder('Teleport')
local folder3 = window:folder('Credits')


-- Game Light button
folder:button({
    name = 'Game Light',
    callback = function()
        local args = { [1] = 'GameLight' }
        game:GetService('ReplicatedStorage')
            :WaitForChild('RemoteEvents', 9e9)
            :WaitForChild('AdminOverrideEvent', 9e9)
            :FireServer(unpack(args))
        print('Game Light activated')
    end,
})

-- Bridge Light button
folder:button({
    name = 'Bridge Light',
    callback = function()
        local args = { [1] = 'BridgeLight' }
        game:GetService('ReplicatedStorage')
            :WaitForChild('RemoteEvents', 9e9)
            :WaitForChild('AdminOverrideEvent', 9e9)
            :FireServer(unpack(args))
        print('Bridge Light activated')
    end,
})

-- Barrier button
folder:button({
    name = 'Barrier',
    callback = function()
        local args = { [1] = 'Barrier' }
        game:GetService('ReplicatedStorage')
            :WaitForChild('RemoteEvents', 9e9)
            :WaitForChild('AdminOverrideEvent', 9e9)
            :FireServer(unpack(args))
        print('Barrier activated')
    end,
})

folder2:button({
    name = 'Teleport to End',
    callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame =
            CFrame.new(212.1660614013672, 172.699951171875, -2.9824163913726807)
    end,
})

folder3:button({
    name = 'Made By UILib',
    callback = function() end,
})

folder3:button({
    name = 'Take What You Want from this',
    callback = function() end,
})

